schema:
entity Book @cache(maxAge: 60s, swr: 300s) { id: ID title: String }
entity Hit { id: ID got: JSON n: Long? }
input Near { maxKm: Int @http(name: "max-km") }
input Where { zipCode: String? @http(name: "zip-code") near: Near? @http(name: "near-by") }
query book(id: ID): Book? @cache(maxAge: 30s, swr: 10s)
query find(firstName: String? @http(name: "first-name"), maxCount: Int? @http(name: "max-count"), n: Long?): Hit @http(method: GET, path: "/find")
query hit(hitId: Long @http(name: "hit-id")): Hit @http(method: GET, path: "/hits/{hitId}")
query search(firstName: String? @http(name: "first-name"), where: Where?): Hit @http(method: QUERY, path: "/search", body: "*")
command tag(hitId: ID @http(name: "hit-id"), where: Where @http(name: "the-where")): Hit @http(method: PUT, path: "/hits/{hitId}", body: where)
